using System.Windows;
using System.Windows.Controls;
namespace WoWItemEditor;
internal sealed class NpcCacheRebuildWindow : Window
{
    private readonly CancellationTokenSource cancel=new();private bool running;internal bool Completed {get;private set;}
    internal NpcCacheRebuildWindow(CatalogResult catalog){Title="Re-evaluate NPC data";Width=780;Height=330;MinWidth=650;MinHeight=300;Owner=null;WindowStartupLocation=WindowStartupLocation.CenterOwner;Background=TooltipView.Brush("#232428");var panel=new StackPanel{Margin=new Thickness(22)};Content=panel;var info=DesignerWindow.Text("Re-checking existing quest givers and rebuilding the NPC cache. This can take time. The previous completed cache stays available until the new scan finishes. Cancelling keeps it unchanged.",15);info.TextWrapping=TextWrapping.Wrap;panel.Children.Add(info);var bar=new ProgressBar{Height=12,Margin=new Thickness(0,20,0,10)};panel.Children.Add(bar);var status=DesignerWindow.Text("Starting…",13);status.TextWrapping=TextWrapping.Wrap;panel.Children.Add(status);var close=DesignerWindow.Button("Cancel scan",panel);close.Click+=(_,_)=>{if(running){cancel.Cancel();status.Text="Cancelling after the current model…";}else Close();};Loaded+=async(_,_)=>{running=true;try{var result=await NpcCache.Rebuild(catalog,(npc,done,total)=>{bar.Maximum=total;bar.Value=done;status.Text=$"Checked {done}/{total} · "+(npc is null?"Appearance not supported":npc.Name);},cancel.Token);Completed=true;status.Text=$"Saved {result.Npcs.Count} viewable NPCs to {NpcCache.Database}. Future openings load this saved list.";}catch(OperationCanceledException){status.Text="Scan cancelled; the previous cache was preserved.";}catch(Exception ex){status.Text="Could not rebuild cache: "+ex.Message;}finally{running=false;close.Content="Close";}};Closing+=(_,e)=>{if(running){cancel.Cancel();e.Cancel=true;}};}
}
